            sign = -1
            number_start = 1
        elif string[0] == "+":
            sign = 1
            number_start = 1
        else:
            sign = 1
            number_start = 0

        # Extract the actual number part (after sign)
        number_string = string[number_start:]

        base = self.base
        # If base wasn't specified, detect it automatically
        if base is None:
            # Check for base prefixes
            if len(number_string) >= 2:
                prefix = number_string[:2].lower()
                if prefix == '0b':
                    base = 2
                    # Remove the prefix for later processing
                    number_string = number_string[2:]
                elif prefix == '0o':
                    base = 8
                    # Remove the prefix for later processing
                    number_string = number_string[2:]
                elif prefix == '0x':
                    base = 16
                    # Remove the prefix for later processing
                    number_string = number_string[2:]
                else:
                    # Assume decimal number, unless different base is detected
                    base = 10
            else:
                base = 10

        # Remove non-base characters
        chars = int_convert.CHARS[:base]
        cleaned_string = re.sub("[^%s]" % chars, "", number_string.lower())

