        key: str,
        cast: typing.Callable[[typing.Any], typing.Any] | None = None,
        default: typing.Any = undefined,
    ) -> typing.Any:
        """
        Get a configuration value from the environment or .env file.

        Args:
            key: The configuration key to look up.
            cast: An optional callable to convert the value.
            default: An optional default value if the key is not found.

        Returns:
            The configuration value.

        Raises:
            KeyError: If the key is not found and no default is provided.
            ValueError: If the cast fails.
        """
        env_key = self.env_prefix + key

        if env_key in self.environ:
            value = self.environ[env_key]
            return self._perform_cast(key, value, cast)

        if key in self.file_values:
            value = self.file_values[key]
            return self._perform_cast(key, value, cast)

        if default is not undefined:
            return self._perform_cast(key, default, cast)

