def simplify_not(expression):
    """
    Demorgan's Law
    NOT (x OR y) -> NOT x AND NOT y
    NOT (x AND y) -> NOT x OR NOT y
    """
    if isinstance(expression, exp.Not):
        this = expression.this
        if is_null(this):
            return exp.null()

        # Handle NOT with comparison operators
        if isinstance(this, exp.Binary) and this.__class__ in COMPLEMENT_COMPARISONS:
            right = this.expression

            # Handle subquery predicates (ALL, ANY)
            if isinstance(right, exp.All) or isinstance(right, exp.Any):
                # Get the complementary predicate class
                if right.__class__ in COMPLEMENT_SUBQUERY_PREDICATES:
                    new_predicate_class = COMPLEMENT_SUBQUERY_PREDICATES[right.__class__]
                    # Create a new predicate with the same subquery
                    new_predicate = new_predicate_class(this=right.this)
                    # Return the complementary comparison with the new predicate
                    return COMPLEMENT_COMPARISONS[this.__class__](this=this.this, expression=new_predicate)

            # Regular complement comparison
            return COMPLEMENT_COMPARISONS[this.__class__](this=this.this, expression=right)

        # Handle NOT with parentheses
        if isinstance(this, exp.Paren):
            condition = this.unnest()

            # Handle NOT with subquery predicates inside parentheses
            if isinstance(condition, exp.Binary) and condition.__class__ in COMPLEMENT_COMPARISONS:
                right = condition.expression
                if isinstance(right, exp.All) or isinstance(right, exp.Any):
                    if right.__class__ in COMPLEMENT_SUBQUERY_PREDICATES:
                        new_predicate_class = COMPLEMENT_SUBQUERY_PREDICATES[right.__class__]
                        new_predicate = new_predicate_class(this=right.this)
                        return COMPLEMENT_COMPARISONS[condition.__class__](this=condition.this, expression=new_predicate)

            # Handle NOT with AND/OR
            if isinstance(condition, exp.And):
                return exp.paren(
                    exp.or_(
                        exp.not_(condition.left, copy=False),
                        exp.not_(condition.right, copy=False),
                        copy=False,
                    )
                )
            if isinstance(condition, exp.Or):
                return exp.paren(
                    exp.and_(
                        exp.not_(condition.left, copy=False),
                        exp.not_(condition.right, copy=False),
                        copy=False,
                    )
                )
            if is_null(condition):
                return exp.null()

        # Handle NOT with boolean literals
        if always_true(this):
            return exp.false()
        if is_false(this):
            return exp.true()

        # Handle double negation
        if isinstance(this, exp.Not):
            # NOT NOT x -> x
            return this.this

