    # Check if stdin display name is excluded
    stdin_excluded = False
    if exclude:
        for pattern in exclude:
            if _fnmatch.fnmatch(stdin_display_name, pattern):
                stdin_excluded = True
                LOG.debug(
                    '"%(path)s" has been excluded',
                    {"path": stdin_display_name},
                )
                break

    # Process each path
    for path in paths:
        # Special handling for stdin
        if path == "-":
            if not stdin_excluded:
                yield path
        else:
            # Normal path processing
            for filename in _filenames_from(path, predicate=is_excluded):
                if (
                    # always lint explicitly passed (even if not matching filter)
                    path == filename
                    # otherwise, check the file against filtered patterns
