from collections.abc import Mapping


def deflate(node, index=None, path=None):
    if index is None:
        index = {}
    if path is None:
        path = []

    # Handle lists and tuples
    if isinstance(node, (list, tuple)):
        return [deflate(item, index, path) for item in node]

    # If not a mapping (dict-like), return as is
    if not isinstance(node, Mapping):
        return node

    # Check if this is an identifiable object (has __typename and id)
    if node and "id" in node and "__typename" in node:
        # Create a cache key using the path, typename and id
        path_str = ":".join(str(p) for p in path) if path else ""
        cache_key = f"{path_str}:{node['__typename']}:{node['id']}"

        # If we've seen this object before, return just the reference
        if index.get(cache_key) is True:
            return {"__typename": node["__typename"], "id": node["id"]}
        else:
            # Mark this object as seen in the cache
            index[cache_key] = True

    result = {}

    # Process each field in the node
    for field_name in node:
        value = node[field_name]
        new_path = path + [field_name]

        # Recursively process the value
        result[field_name] = deflate(value, index, new_path)

    return result
</parameter>
