import os
from typing import TYPE_CHECKING, Any, Dict, List, Match, Set, Union

from ._base import BaseDirective, DirectivePlugin

if TYPE_CHECKING:
    from ..block_parser import BlockParser
    from ..core import BaseRenderer, BlockState
    from ..markdown import Markdown

class Include(DirectivePlugin):
    def parse(
        self, block: "BlockParser", m: Match[str], state: "BlockState"
    ) -> Union[Dict[str, Any], List[Dict[str, Any]]]:
        source_file = state.env.get("__file__")

        # Issue 1: Check if source file is missing in the environment
        if source_file is None:
            return {
                'type': 'block_error',
                'raw': 'Error: Source file is missing in the environment. Cannot resolve relative path.',
            }

        encoding = 'utf-8'
        options = self.parse_options(m)
        if options:
            attrs = dict(options)
            if 'encoding' in attrs:
                encoding = attrs['encoding']
        else:
            attrs = {}

        relpath = self.parse_title(m)
        dest = os.path.join(os.path.dirname(source_file), relpath)
        dest = os.path.normpath(dest)

        # Issue 3: Check for self-inclusion
        if dest == source_file:
            return {
                'type': 'block_error',
                'raw': 'Error: Could not include self: ' + relpath,
            }

        # Check for recursive inclusion
        included_files = state.env.get('__included_files__', set())
        if dest in included_files:
            return {
                'type': 'block_error',
                'raw': f'Error: Recursive inclusion detected for file: {relpath}',
            }

        # Issue 2: Check if the included file exists
        if not os.path.exists(dest):
            return {
                'type': 'block_error',
                'raw': f'Error: File not found: {relpath}',
            }

        # Check if it's a directory
        if os.path.isdir(dest):
            return {
                'type': 'block_error',
                'raw': f'Error: Cannot include a directory: {relpath}',
            }

        try:
            with open(dest, 'rb') as f:
                content = f.read().decode(encoding)
        except Exception as e:
            return {
                'type': 'block_error',
                'raw': f'Error reading file {relpath}: {str(e)}',
            }

        ext = os.path.splitext(relpath)[1]
        if ext in {'.md', '.markdown', '.mkd'}:
            # Track included files to prevent recursive inclusion
            new_included_files = included_files.copy()
            new_included_files.add(dest)

            new_state = block.state_cls()
            new_state.env['__file__'] = dest
            new_state.env['__included_files__'] = new_included_files
            new_state.process(content)
            block.parse(new_state)
            return new_state.tokens

        elif ext in {'.html', '.xhtml', '.htm'}:
            return {'type': 'block_html', 'raw': content}

        attrs['filepath'] = dest
        return {
            'type': 'include',
            'raw': content,
            'attrs': attrs,
        }

    def __call__(self, directive: BaseDirective, md: "Markdown") -> None:
        directive.register("include", self.parse)
        if md.renderer and md.renderer.NAME == "html":
            md.renderer.register("include", render_html_include)


