def _make_getter(regex):
    if regex.groups == 0:
        return methodcaller('group', 0)
    elif regex.groups == 1:
        return methodcaller('group', 1)
    elif not regex.groupindex:
        return lambda m: tuple(m.group(i) for i in range(1, regex.groups + 1))
    else:
        # For mixed named and unnamed groups, we need to handle both
        if len(regex.groupindex) == regex.groups:
            # All groups are named
            return lambda m: {name: m.group(name) for name in regex.groupindex}
        else:
            # Mix of named and unnamed groups - return a tuple for consistency with test_strings.py
            return lambda m: tuple(m.group(i) for i in range(1, regex.groups + 1))
