def wrap_coroutine(api: Any, coroutine: _CallableT) -> _CallableT:
    @functools.wraps(coroutine)
    async def wrapper(*args: Any, **kwargs: Any) -> Any:
        with api as time_factory:
            if api.as_arg and api.as_kwarg:
                assert False, "You can't specify both as_arg and as_kwarg at the same time. Pick one."
            elif api.as_arg:
                result = await coroutine(time_factory, *args, **kwargs)
            elif api.as_kwarg:
                kwargs[api.as_kwarg] = time_factory
                result = await coroutine(*args, **kwargs)
            else:
                result = await coroutine(*args, **kwargs)
        return result

    return cast(_CallableT, wrapper)
