def raise_from_error(error, params=None):
    """
    Raise an OAuth2Error or subclass based on the error code.

    :param error: A string representing the error code, e.g., 'invalid_request'.
    :param params: A dict containing additional parameters to pass to the error constructor.
                  Expected keys include 'error_description', 'error_uri', and 'state'.
    :raises: OAuth2Error or a subclass based on the error code.
    """
    import sys
    import inspect

    # Handle edge cases for error parameter
    if error is None:
        error = 'server_error'

    # Ensure error is a string
    try:
        error = str(error)
    except Exception:
        error = 'server_error'

    # Handle edge cases for params parameter
    if params is None:
        params = {}
    elif not isinstance(params, dict):
        # If params is not a dict, create a dict with a description of the issue
        params = {'error_description': f'Invalid params type: {type(params).__name__}'}

    # Extract parameters from the params dict
    kwargs = {
        'description': params.get('error_description') if hasattr(params, 'get') else None,
        'uri': params.get('error_uri') if hasattr(params, 'get') else None,
        'state': params.get('state') if hasattr(params, 'get') else None
    }

    try:
        # First, try to find an exact match for the error class name
        # For example, 'invalid_request' should map to InvalidRequestError
        error_class_name = ''.join(word.capitalize() for word in error.split('_')) + 'Error'
        for name, cls in inspect.getmembers(sys.modules[__name__], inspect.isclass):
            if name == error_class_name and issubclass(cls, OAuth2Error):
                raise cls(**kwargs)

        # If no exact match, find any class with matching error code
        for _, cls in inspect.getmembers(sys.modules[__name__], inspect.isclass):
            if hasattr(cls, 'error') and cls.error == error and issubclass(cls, OAuth2Error):
                # Prefer the base error class if available (e.g., InvalidRequestError over InvalidClientIdError)
                if cls.__name__ == error_class_name:
                    raise cls(**kwargs)

        # Try one more time with any matching error
        for _, cls in inspect.getmembers(sys.modules[__name__], inspect.isclass):
            if hasattr(cls, 'error') and cls.error == error and issubclass(cls, OAuth2Error):
                raise cls(**kwargs)
    except Exception as e:
        # If anything goes wrong during error class lookup, fall back to CustomOAuth2Error
        # but include the original exception in the description
        kwargs['description'] = f"{kwargs.get('description', '')} (Error during lookup: {str(e)})"

    # If no matching class is found, use CustomOAuth2Error
    raise CustomOAuth2Error(error=error, **kwargs)
