    def encodeValue(self, value, asn1Spec, encodeFun, **options):

        numbers = value.asNumbers()

        if self.PLUS_CHAR in numbers or self.MINUS_CHAR in numbers:
            raise error.PyAsn1Error('Must be UTC time: %r' % value)

        if numbers[-1] != self.Z_CHAR:
            raise error.PyAsn1Error('Missing "Z" time zone specifier: %r' % value)

        if self.COMMA_CHAR in numbers:
            raise error.PyAsn1Error('Comma in fractions disallowed: %r' % value)

        if self.DOT_CHAR in numbers:
            numbers = list(numbers)
            dot_index = numbers.index(self.DOT_CHAR)

            # Find the last non-zero digit in the fraction part
            last_non_zero = None
            for i in range(dot_index + 1, len(numbers) - 1):  # -1 to exclude 'Z'
                if numbers[i] != self.ZERO_CHAR:
                    last_non_zero = i

            if last_non_zero is None:
                # All zeros in fraction or empty fraction - remove the dot and all zeros
                numbers = numbers[:dot_index] + numbers[-1:]  # Keep only the 'Z'
            else:
                # Remove trailing zeros
                numbers = numbers[:last_non_zero + 1] + numbers[-1:]  # Keep up to last non-zero + 'Z'

        if not self.MIN_LENGTH < len(numbers) < self.MAX_LENGTH:
            raise error.PyAsn1Error('Length constraint violated: %r' % value)

        options.update(maxChunkSize=1000)

        # Convert back to bytes if we modified the numbers
        if isinstance(numbers, list):
            value = useful.GeneralizedTime(bytes(numbers))

        return encoder.OctetStringEncoder.encodeValue(
            self, value, asn1Spec, encodeFun, **options
        )
